import java.util.Deque;
import java.util.ArrayDeque;

public class BrowserHistoryExample {
    public static void main(String[] args) {
        Deque<String> history = new ArrayDeque<>();

        // Add five page URLs
        history.addFirst("https://example.com/home");
        history.addFirst("https://example.com/about");
        history.addFirst("https://example.com/services");
        history.addFirst("https://example.com/contact");
        history.addFirst("https://example.com/blog");

        System.out.println("Browser history:");
        history.forEach(System.out::println);

        // Simulate going back (poll from the front)
        String lastVisited = history.pollFirst();
        System.out.println("\nGo back: remove current page (front): " + lastVisited);
        System.out.println("Current history: ");
        history.forEach(System.out::println);

        // Clear the two oldest entries from the back
        String oldest1 = history.pollLast();
        String oldest2 = history.pollLast();
        System.out.println("\nClear oldest pages from the back: " + oldest1 + ", " + oldest2);
        System.out.println("Current history: ");
        history.forEach(System.out::println);
    }
}
